const plan = $('Waiting for Student Revision').first().json.body.plan;
const s = $('Student Submits').first().json.body;

// ---------- helpers ----------
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tidyTime = (t) => esc(t).replace(/(\d{1,2}:\d{2}):00/g, '$1');
const firstName = esc(String(s.fullName ?? '').trim().split(/\s+/)[0] || 'Student');

// ---------- course table (same design as the advisor email) ----------
const hasSection = plan.courses.some(c => c.section);

const th = (label, align = 'left') =>
  `<th style="background:#1f3a5f;color:#ffffff;padding:10px 12px;text-align:${align};
   font-size:13px;font-weight:600;border-bottom:2px solid #16304f;">${label}</th>`;

const td = (value, i, align = 'left', bold = false) =>
  `<td style="padding:10px 12px;font-size:13px;color:#1f2933;text-align:${align};
   background:${i % 2 ? '#f4f7fb' : '#ffffff'};border-bottom:1px solid #e3e8ef;
   ${bold ? 'font-weight:600;' : ''}">${value}</td>`;

const rows = plan.courses.map((c, i) => `
  <tr>
    ${td(esc(c.code), i, 'left', true)}
    ${hasSection ? td(esc(c.section), i, 'center') : ''}
    ${td(esc(c.title), i)}
    ${td(esc(c.days), i, 'center')}
    ${td(tidyTime(c.time), i)}
    ${td(esc(c.instructor), i)}
    ${td(esc(c.room), i, 'center')}
    ${td(esc(c.credits), i, 'center')}
  </tr>`).join('');

const colCount = hasSection ? 8 : 7;

const courseTable = `
  <table cellpadding="0" cellspacing="0" width="100%"
         style="border-collapse:collapse;border:1px solid #e3e8ef;">
    <tr>
      ${th('Code')}
      ${hasSection ? th('Sec.', 'center') : ''}
      ${th('Course Title')}
      ${th('Days', 'center')}
      ${th('Time')}
      ${th('Instructor')}
      ${th('Room', 'center')}
      ${th('Cr.', 'center')}
    </tr>
    ${rows}
    <tr>
      <td colspan="${colCount - 1}" style="padding:12px;font-size:13px;font-weight:700;
          text-align:right;background:#e8eef6;">Total Credits</td>
      <td style="padding:12px;font-size:14px;font-weight:700;text-align:center;
          background:#e8eef6;color:#1f3a5f;">${esc(plan.totalCredits)}</td>
    </tr>
  </table>
  <p style="font-size:12px;color:#6b7785;margin-top:10px;">
    Days: M = Monday, T = Tuesday, W = Wednesday, R = Thursday, F = Friday.
  </p>`;

const banner = (bg, border, color, text) => `
  <div style="background:${bg};border-left:4px solid ${border};padding:14px 16px;
       margin:0 0 20px 0;font-size:15px;font-weight:700;color:${color};">${text}</div>`;

// ---------- approval email ----------
const html = `
<div style="font-family:Arial,Helvetica,sans-serif;max-width:760px;color:#1f2933;">
  ${banner('#e7f6ec', '#1e8e3e', '#14632b', '&#10003; Your registration plan has been approved')}

  <p style="font-size:14px;">Dear ${firstName},</p>

  <p style="font-size:14px;line-height:1.6;">
    Congratulations! Your advisor has reviewed and <b>approved</b> your proposed schedule for
    <b>${esc(s.semester)} ${esc(s.year)}</b>.
  </p>

  <p style="font-size:14px;line-height:1.6;">
    You have been <b>unblocked on RHU SIS</b>, so you can now go ahead and register
    for the courses below.
  </p>

  <h3 style="font-size:15px;color:#1f3a5f;margin:24px 0 10px 0;">Your approved schedule</h3>
  ${courseTable}

  <p style="font-size:14px;line-height:1.6;margin-top:20px;">
    Please register for these exact sections on SIS as soon as possible, since seats can fill up.
  </p>

  <p style="font-size:14px;line-height:1.6;">
    Wishing you a great semester!<br>
    <b>RHU CourseFlow</b>
  </p>
</div>`;

return [{
  json: {
    to: s.email,
    subject: `Approved: your ${s.semester} ${s.year} registration plan`,
    html,
  },
}];

